[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "quinoa-vs-rice-comparison",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "quinoa-vs-rice-comparison",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              "title",
              "summary",
              "divider_1",
              "table_title",
              "comparison_table",
              "divider_2",
              "gi_notes_card",
              "divider_3",
              "actions_title",
              "actions_row",
              "divider_4",
              "assumptions_text"
            ]
          }
        },
        {
          "id": "title",
          "type": "Text",
          "properties": {
            "text": "Quinoa vs. Brown Rice: A Nutritional Comparison",
            "style": "headline-sm"
          }
        },
        {
          "id": "summary",
          "type": "Text",
          "properties": {
            "text": "Both cooked quinoa and cooked brown rice are nutritious whole grains, offering good sources of protein and fiber. Quinoa generally provides a higher protein and fiber content per 100g serving compared to brown rice. Their glycemic index values are similar, both falling into the moderate category."
          }
        },
        {
          "id": "divider_1",
          "type": "Divider"
        },
        {
          "id": "table_title",
          "type": "Text",
          "properties": {
            "text": "Nutritional Profile (per 100g cooked)",
            "style": "title-md"
          }
        },
        {
          "id": "comparison_table",
          "type": "Table",
          "properties": {
            "columns": [
              {
                "header": "Nutrient"
              },
              {
                "header": "Cooked Quinoa (100g)",
                "horizontalAlignment": "end"
              },
              {
                "header": "Cooked Brown Rice (100g)",
                "horizontalAlignment": "end"
              }
            ],
            "rows": [
              {
                "cells": [
                  {
                    "text": "Protein"
                  },
                  {
                    "text": "~4.4 grams"
                  },
                  {
                    "text": "~2.7 grams"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "text": "Fiber"
                  },
                  {
                    "text": "~2.8 grams"
                  },
                  {
                    "text": "~1.8 grams"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "text": "Glycemic Index (GI)"
                  },
                  {
                    "text": "~53 (Moderate)"
                  },
                  {
                    "text": "~55 (Moderate)"
                  }
                ]
              }
            ]
          }
        },
        {
          "id": "divider_2",
          "type": "Divider"
        },
        {
          "id": "gi_notes_card",
          "type": "Card",
          "properties": {
            "child": "gi_notes_column"
          }
        },
        {
          "id": "gi_notes_column",
          "type": "Column",
          "properties": {
            "children": [
              "gi_notes_title",
              "gi_notes_list",
              "gi_notes_summary"
            ]
          }
        },
        {
          "id": "gi_notes_title",
          "type": "Text",
          "properties": {
            "text": "Glycemic Index Notes",
            "style": "title-sm"
          }
        },
        {
          "id": "gi_notes_list",
          "type": "List",
          "properties": {
            "children": [
              "gi_low",
              "gi_mod",
              "gi_high"
            ]
          }
        },
        {
          "id": "gi_low",
          "type": "ListItem",
          "properties": {
            "primaryText": "A Glycemic Index (GI) of 55 or less is considered low."
          }
        },
        {
          "id": "gi_mod",
          "type": "ListItem",
          "properties": {
            "primaryText": "A GI between 56 and 69 is considered moderate."
          }
        },
        {
          "id": "gi_high",
          "type": "ListItem",
          "properties": {
            "primaryText": "A GI of 70 or higher is considered high."
          }
        },
        {
          "id": "gi_notes_summary",
          "type": "Text",
          "properties": {
            "text": "Both quinoa and brown rice fall within the moderate GI range, meaning they cause a relatively steady rise in blood sugar compared to high GI foods."
          }
        },
        {
          "id": "divider_3",
          "type": "Divider"
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "title-md"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "children": [
              "quinoa_button",
              "rice_button"
            ]
          }
        },
        {
          "id": "quinoa_button",
          "type": "Button",
          "properties": {
            "label": "Explore Quinoa Recipes",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "https://example.com/quinoa-recipes"
                }
              }
            }
          }
        },
        {
          "id": "rice_button",
          "type": "Button",
          "properties": {
            "label": "Explore Brown Rice Recipes",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "https://example.com/brown-rice-recipes"
                }
              }
            }
          }
        },
        {
          "id": "divider_4",
          "type": "Divider"
        },
        {
          "id": "assumptions_text",
          "type": "Text",
          "properties": {
            "text": "Assumptions:\n- Nutritional values are based on 100g of cooked, plain quinoa and 100g of cooked, plain long-grain brown rice, prepared with water and no added fats or seasonings.\n- Glycemic Index (GI) values are approximate and can vary based on preparation, specific variety, and individual metabolic response.",
            "style": "body-sm"
          }
        }
      ]
    }
  }
]
